__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"AIHM_KARARLAR",{enumerable:!0,get:function(){return l}}),e.aihmKategoriler=function(){return Array.from(new Set(l.map(l=>l.kategori)))},e.searchAihm=function(n){const k=n.trim().toLocaleLowerCase('tr');return k?l.filter(l=>[l.basvuru,l.kategori,l.madde,l.ilke,l.olay,l.degerlendirme,l.onem].join(' ').toLocaleLowerCase('tr').includes(k)):l};const l=[{id:'handyside-1976',slug:'handyside-birlesik-krallik',basvuru:'Handyside / Birle\u015fik Krall\u0131k',basvuruNo:'5493/72',tarih:'07.12.1976',madde:'A\u0130HS m. 10 (\u0130fade \xf6zg\xfcrl\xfc\u011f\xfc)',kategori:'\u0130fade \xd6zg\xfcrl\xfc\u011f\xfc',ilke:'\u0130fade \xf6zg\xfcrl\xfc\u011f\xfc yaln\u0131zca lehte veya zarars\u0131z g\xf6r\xfclen bilgiler i\xe7in de\u011fil; devleti veya toplumun bir kesimini \u201crahats\u0131z eden, \u015foke eden ya da endi\u015felendiren\u201d d\xfc\u015f\xfcnceler i\xe7in de ge\xe7erlidir. Bunlar \xe7o\u011fulculu\u011fun, ho\u015fg\xf6r\xfcn\xfcn ve a\xe7\u0131k fikirlili\u011fin gere\u011fidir.',olay:'Yay\u0131nc\u0131 Handyside, gen\xe7lere y\xf6nelik \u201cThe Little Red Schoolbook\u201d adl\u0131 kitab\u0131 yay\u0131mlam\u0131\u015f; kitap \u0130ngiltere\u2019nin m\xfcstehcen yay\u0131n mevzuat\u0131 uyar\u0131nca toplat\u0131l\u0131p imha edilmi\u015f, yay\u0131nc\u0131 cezaland\u0131r\u0131lm\u0131\u015ft\u0131r. Handyside bunun ifade \xf6zg\xfcrl\xfc\u011f\xfcn\xfc ihlal etti\u011fini ileri s\xfcrm\xfc\u015ft\xfcr.',degerlendirme:'Mahkeme, \u201cahlak\u0131n korunmas\u0131\u201dn\u0131 me\u015fru ama\xe7 saym\u0131\u015f; ulusal makamlar\u0131n toplumsal ihtiyac\u0131 de\u011ferlendirmede uluslararas\u0131 yarg\u0131\xe7tan daha iyi konumda oldu\u011funu belirterek devletlere bir \u201ctakdir marj\u0131\u201d (margin of appreciation) tan\u0131m\u0131\u015ft\u0131r. Ancak bu marj Mahkeme\u2019nin denetimine tabidir; m\xfcdahalenin \u201cdemokratik toplumda gerekli\u201d ve g\xfcd\xfclen ama\xe7la orant\u0131l\u0131 olmas\u0131 aran\u0131r.',sonuc:'m. 10 ihlali bulunmad\u0131 \u2014 m\xfcdahale gerekli ve orant\u0131l\u0131 kabul edildi.',onem:'\u0130fade \xf6zg\xfcrl\xfc\u011f\xfc i\xe7tihad\u0131n\u0131n temel ta\u015f\u0131d\u0131r. \u201cTakdir marj\u0131\u201d ve \u201cdemokratik toplumda gereklilik\u201d testleri, A\u0130HM\u2019in ve T\xfcrk Anayasa Mahkemesi\u2019nin ifade \xf6zg\xfcrl\xfc\u011f\xfc de\u011ferlendirmelerinde bug\xfcn de belirleyicidir.'},{id:'golder-1975',slug:'golder-birlesik-krallik',basvuru:'Golder / Birle\u015fik Krall\u0131k',basvuruNo:'4451/70',tarih:'21.02.1975',madde:'A\u0130HS m. 6/1, m. 8',kategori:'Adil Yarg\u0131lanma',ilke:'Adil yarg\u0131lanma hakk\u0131, \u201cmahkemeye eri\u015fim hakk\u0131n\u0131\u201d da i\xe7erir. Dava a\xe7abilme imk\xe2n\u0131 tan\u0131nmadan yarg\u0131lama g\xfcvencelerinden s\xf6z edilemez.',olay:'Cezaevindeki ba\u015fvurucu, bir gardiyan\u0131n kendisine y\xf6nelik iddialar\u0131na kar\u015f\u0131 hakaret davas\u0131 a\xe7mak \xfczere avukatla g\xf6r\xfc\u015fmek istemi\u015f; idare bu izni vermemi\u015ftir.',degerlendirme:'Mahkeme, m. 6/1 a\xe7\u0131k\xe7a \u201cmahkemeye eri\u015fim\u201d demese de h\xfckm\xfcn amac\u0131n\u0131n bunu i\xe7erdi\u011fini; eri\u015fim hakk\u0131 olmadan usuli g\xfcvencelerin anlams\u0131z kalaca\u011f\u0131n\u0131 belirtmi\u015ftir. Avukatla g\xf6r\xfc\u015fmenin engellenmesi hem eri\u015fim hakk\u0131n\u0131 hem de haberle\u015fmeye sayg\u0131y\u0131 zedelemi\u015ftir.',sonuc:'m. 6/1 ve m. 8 ihlali.',onem:'Mahkemeye eri\u015fim hakk\u0131n\u0131n anayasal-s\xf6zle\u015fmesel temelini kuran karard\u0131r. T\xfcrkiye\u2019de dava \u015fartlar\u0131, har\xe7 ve eri\u015fim engellerinin \xf6l\xe7\xfcl\xfcl\xfc\u011f\xfc tart\u0131\u015fmalar\u0131nda dayanak olu\u015fturur.'},{id:'airey-1979',slug:'airey-irlanda',basvuru:'Airey / \u0130rlanda',basvuruNo:'6289/73',tarih:'09.10.1979',madde:'A\u0130HS m. 6/1, m. 8',kategori:'Adil Yarg\u0131lanma',ilke:'S\xf6zle\u015fme, haklar\u0131 \u201cteorik ve yan\u0131lsamal\u0131 de\u011fil, pratik ve etkili\u201d bi\xe7imde g\xfcvence alt\u0131na al\u0131r. Baz\u0131 h\xe2llerde mahkemeye etkili eri\u015fim, devletin adli yard\u0131m sa\u011flama gibi pozitif edimlerini gerektirir.',olay:'Maddi imk\xe2n\u0131 k\u0131s\u0131tl\u0131 ba\u015fvurucu, e\u015finden ayr\u0131l\u0131k (judicial separation) karar\u0131 almak istemi\u015f; ancak dava yaln\u0131zca \xfcst derece mahkemesinde ve fiilen avukatla y\xfcr\xfct\xfclebildi\u011finden, adli yard\u0131m da bulunmad\u0131\u011f\u0131ndan davas\u0131n\u0131 a\xe7amam\u0131\u015ft\u0131r.',degerlendirme:'Mahkeme, hakk\u0131n k\xe2\u011f\u0131t \xfczerinde tan\u0131nmas\u0131n\u0131n yetmedi\u011fini; davan\u0131n karma\u015f\u0131kl\u0131\u011f\u0131 ve duygusal y\xfck\xfc kar\u015f\u0131s\u0131nda avukats\u0131z etkili eri\u015fimin ger\xe7ek\xe7i olmad\u0131\u011f\u0131n\u0131 belirtmi\u015ftir. Devletin s\xf6zle\u015fmesel y\xfck\xfcml\xfcl\xfc\u011f\xfc, gerekti\u011finde eri\u015fimi fiilen m\xfcmk\xfcn k\u0131lacak tedbirleri de kapsar.',sonuc:'m. 6/1 ihlali (ve \xf6zel/aile ya\u015fam\u0131 y\xf6n\xfcnden m. 8 ihlali).',onem:'\u201cPratik ve etkili koruma\u201d ilkesinin ve adli yard\u0131m\u0131n s\xf6zle\u015fmesel temelinin kayna\u011f\u0131d\u0131r. Adli yard\u0131m/eri\u015fim davalar\u0131nda yerle\u015fik at\u0131f noktas\u0131d\u0131r.'},{id:'soering-1989',slug:'soering-birlesik-krallik',basvuru:'Soering / Birle\u015fik Krall\u0131k',basvuruNo:'14038/88',tarih:'07.07.1989',madde:'A\u0130HS m. 3 (\u0130\u015fkence ve k\xf6t\xfc muamele yasa\u011f\u0131)',kategori:'\u0130\u015fkence Yasa\u011f\u0131',ilke:'Bir ki\u015fiyi, gidece\u011fi \xfclkede m. 3\u2019e ayk\u0131r\u0131 muameleye maruz kalaca\u011f\u0131na dair ger\xe7ek bir risk (real risk) varsa iade/s\u0131n\u0131rd\u0131\u015f\u0131 eden devlet sorumlu olur. Bu koruma, S\xf6zle\u015fme\u2019ye taraf olmayan \xfclkelere iadede de ge\xe7erlidir.',olay:'Almanya uyruklu ba\u015fvurucu, ABD\u2019nin Virginia eyaletine iade edildi\u011finde idam cezas\u0131 ve infaz \xf6ncesi y\u0131llarca s\xfcren \u201c\xf6l\xfcm koridoru sendromu\u201d (death row phenomenon) ile kar\u015f\u0131la\u015facakt\u0131.',degerlendirme:'Mahkeme, m. 3\u2019\xfcn mutlak niteli\u011finden hareketle, iade sonras\u0131 \xf6ng\xf6r\xfclebilir muamelenin insanl\u0131k d\u0131\u015f\u0131 olmas\u0131 h\xe2linde sorumlulu\u011fun iade eden devlete de do\u011faca\u011f\u0131n\u0131 belirtmi\u015ftir. \xd6l\xfcm koridorundaki bekleyi\u015f ko\u015fullar\u0131, ya\u015f ve ruh h\xe2li birlikte de\u011ferlendirilmi\u015ftir.',sonuc:'\u0130ade ger\xe7ekle\u015fseydi m. 3 ihlali olu\u015facakt\u0131 (iade engellendi).',onem:'S\u0131n\u0131rd\u0131\u015f\u0131/iade ve geri g\xf6nderme (non-refoulement) hukukunun temel karar\u0131d\u0131r. T\xfcrkiye\u2019deki geri g\xf6nderme, iade ve uluslararas\u0131 koruma uyu\u015fmazl\u0131klar\u0131nda do\u011frudan dayanakt\u0131r.'},{id:'osman-1998',slug:'osman-birlesik-krallik',basvuru:'Osman / Birle\u015fik Krall\u0131k',basvuruNo:'23452/94',tarih:'28.10.1998',buyukDaire:!0,madde:'A\u0130HS m. 2 (Ya\u015fam hakk\u0131), m. 6',kategori:'Ya\u015fam Hakk\u0131',ilke:'\u201cOsman testi\u201d: Devletin ya\u015fam hakk\u0131n\u0131 koruma pozitif y\xfck\xfcml\xfcl\xfc\u011f\xfc, yetkililerin belirli bir ki\u015fiye y\xf6nelik ger\xe7ek ve yak\u0131n (real and immediate) ya\u015fam riskini bildi\u011fi ya da bilmesi gerekti\u011fi ve makul tedbirleri almad\u0131\u011f\u0131 h\xe2llerde do\u011far.',olay:'Bir \xf6\u011fretmenin \xf6\u011frencisine y\xf6nelik saplant\u0131l\u0131 davran\u0131\u015flar\u0131 giderek tehdide d\xf6n\xfc\u015fm\xfc\u015f; nihayetinde \xf6\u011frencinin babas\u0131 \xf6ld\xfcr\xfclm\xfc\u015f, kendisi yaralanm\u0131\u015ft\u0131r. Aile, polisin uyar\u0131lara ra\u011fmen \xf6nlem almad\u0131\u011f\u0131n\u0131 ileri s\xfcrm\xfc\u015ft\xfcr.',degerlendirme:'Mahkeme, pozitif y\xfck\xfcml\xfcl\xfc\u011f\xfc kabul etmekle birlikte bunun makull\xfck e\u015fi\u011fiyle s\u0131n\u0131rl\u0131 oldu\u011funu; somut olayda yetkililerin belirleyici anda ger\xe7ek ve yak\u0131n riski bilmesi gerekti\u011finin kan\u0131tlanamad\u0131\u011f\u0131n\u0131 belirtmi\u015ftir. Ayr\u0131ca polise mutlak dokunulmazl\u0131k tan\u0131nmas\u0131 mahkemeye eri\u015fimi zedelemi\u015ftir.',sonuc:'m. 2 ihlali bulunmad\u0131; ancak m. 6/1 (mahkemeye eri\u015fim) ihlali.',onem:'Devletin bireyi \xfc\xe7\xfcnc\xfc ki\u015filere kar\u015f\u0131 koruma y\xfck\xfcml\xfcl\xfc\u011f\xfcn\xfcn \xf6l\xe7\xfct\xfcn\xfc (Osman testi) kuran karard\u0131r. Kad\u0131na y\xf6nelik \u015fiddet, tehdit ve koruma tedbiri davalar\u0131nda yayg\u0131n dayanakt\u0131r.'},{id:'klass-1978',slug:'klass-almanya',basvuru:'Klass ve Di\u011ferleri / Almanya',basvuruNo:'5029/71',tarih:'06.09.1978',madde:'A\u0130HS m. 8 (\xd6zel hayat), m. 13',kategori:'\xd6zel Hayat',ilke:'Gizli g\xf6zetim/ileti\u015fimin denetlenmesi \xf6zel hayata ve haberle\u015fmeye m\xfcdahaledir. Ancak keyfili\u011fe kar\u015f\u0131 yeterli ve etkili g\xfcvenceler (ba\u011f\u0131ms\u0131z denetim) bulunuyorsa demokratik toplumda gerekli say\u0131labilir.',olay:'Alman mevzuat\u0131, milli g\xfcvenlik gerek\xe7esiyle ki\u015fiye bildirim yap\u0131lmaks\u0131z\u0131n haberle\u015fmenin gizlice izlenmesine imk\xe2n tan\u0131yordu. Ba\u015fvurucular bu d\xfczenlemenin \xf6zel hayat\u0131 ihlal etti\u011fini ileri s\xfcrd\xfcler.',degerlendirme:'Mahkeme, casusluk ve ter\xf6rle m\xfccadelede gizli izleme tedbirlerinin gerekli olabilece\u011fini kabul etmi\u015f; fakat \u201cdemokrasiyi savunma ad\u0131na onu tahrip etme\u201d tehlikesine kar\u015f\u0131 yeterli g\xfcvence ve denetim mekanizmas\u0131 aram\u0131\u015ft\u0131r. Somut mevzuattaki g\xfcvenceler yeterli g\xf6r\xfclm\xfc\u015ft\xfcr.',sonuc:'m. 8 ve m. 13 ihlali bulunmad\u0131 \u2014 fakat gizli g\xf6zetimin denetim standard\u0131 kuruldu.',onem:'Kitlesel/gizli g\xf6zetim, dinleme ve veri toplama denetiminin \xe7er\xe7eve karar\u0131d\u0131r. \u0130leti\u015fimin denetlenmesi ve ki\u015fisel veri uyu\u015fmazl\u0131klar\u0131nda \xf6l\xe7\xfct sunar.'},{id:'kudla-2000',slug:'kudla-polonya',basvuru:'Kud\u0142a / Polonya',basvuruNo:'30210/96',tarih:'26.10.2000',buyukDaire:!0,madde:'A\u0130HS m. 6/1, m. 13',kategori:'Adil Yarg\u0131lanma',ilke:'Makul s\xfcrede yarg\u0131lanma hakk\u0131n\u0131n ihlaline kar\u015f\u0131, i\xe7 hukukta bu ihlali \xf6nleyen veya gideren etkili bir ba\u015fvuru yolu (m. 13) bulunmak zorundad\u0131r.',olay:'Ba\u015fvurucu, ceza yarg\u0131lamas\u0131n\u0131n a\u015f\u0131r\u0131 uzun s\xfcrd\xfc\u011f\xfcn\xfc; \xfcstelik i\xe7 hukukta bu gecikmeye kar\u015f\u0131 ba\u015fvurabilece\u011fi etkili bir yol bulunmad\u0131\u011f\u0131n\u0131 ileri s\xfcrm\xfc\u015ft\xfcr.',degerlendirme:'Mahkeme, m. 13\u2019\xfcn makul s\xfcre \u015fik\xe2yetleri bak\u0131m\u0131ndan da ayr\u0131 ve ba\u011f\u0131ms\u0131z bir g\xfcvence olu\u015fturdu\u011funu; devletlerin uzun yarg\u0131lamalara kar\u015f\u0131 ulusal d\xfczeyde etkili (tazminat ve/veya h\u0131zland\u0131r\u0131c\u0131) bir yol kurmakla y\xfck\xfcml\xfc oldu\u011funu belirtmi\u015ftir.',sonuc:'m. 13 ihlali (ve makul s\xfcre y\xf6n\xfcnden m. 6/1 ihlali).',onem:'T\xfcrkiye\u2019de uzun yarg\u0131lama ve gecikmelere kar\u015f\u0131 Tazminat Komisyonu ve Anayasa Mahkemesi bireysel ba\u015fvuru yolunun etkinli\u011fi tart\u0131\u015fmalar\u0131n\u0131n do\u011frudan kayna\u011f\u0131d\u0131r.'},{id:'selmouni-1999',slug:'selmouni-fransa',basvuru:'Selmouni / Fransa',basvuruNo:'25803/94',tarih:'28.07.1999',buyukDaire:!0,madde:'A\u0130HS m. 3 (\u0130\u015fkence yasa\u011f\u0131)',kategori:'\u0130\u015fkence Yasa\u011f\u0131',ilke:'S\xf6zle\u015fme \u201cya\u015fayan bir belge\u201ddir; artan insan haklar\u0131 standartlar\u0131 kar\u015f\u0131s\u0131nda, ge\xe7mi\u015fte \u201cinsanl\u0131k d\u0131\u015f\u0131 muamele\u201d say\u0131lan fiiller bug\xfcn \u201ci\u015fkence\u201d olarak nitelenebilir.',olay:'Ba\u015fvurucu, g\xf6zalt\u0131ndayken kolluk g\xf6revlilerince tekrarlanan a\u011f\u0131r fiziksel \u015fiddete ve a\u015fa\u011f\u0131lay\u0131c\u0131 muameleye maruz kald\u0131\u011f\u0131n\u0131, bunun sa\u011fl\u0131k raporlar\u0131yla da sabit oldu\u011funu ileri s\xfcrm\xfc\u015ft\xfcr.',degerlendirme:'Mahkeme, g\xf6zalt\u0131ndaki bir ki\u015finin yaralanmalar\u0131n\u0131n makul bi\xe7imde a\xe7\u0131klanmas\u0131 y\xfck\xfcn\xfcn devlete ait oldu\u011funu vurgulam\u0131\u015f; muamelenin a\u011f\u0131rl\u0131\u011f\u0131 ve kas\u0131t unsuru kar\u015f\u0131s\u0131nda bunu \u201ci\u015fkence\u201d olarak nitelemi\u015f, koruma standard\u0131n\u0131n zamanla y\xfckseldi\u011fini belirtmi\u015ftir.',sonuc:'m. 3 (i\u015fkence) ihlali.',onem:'G\xf6zalt\u0131nda k\xf6t\xfc muamelede ispat y\xfck\xfc ve \u201ci\u015fkence\u201d nitelemesinin evrilen \xf6l\xe7\xfct\xfc bak\u0131m\u0131ndan temel karard\u0131r. T\xfcrkiye\u2019ye kar\u015f\u0131 k\xf6t\xfc muamele davalar\u0131nda yayg\u0131n at\u0131ft\u0131r.'},{id:'loizidou-1996',slug:'loizidou-turkiye',basvuru:'Loizidou / T\xfcrkiye (Esas)',basvuruNo:'15318/89',tarih:'18.12.1996',buyukDaire:!0,madde:'A\u0130HS m. 1; 1 No\u2019lu Protokol m. 1 (M\xfclkiyet)',kategori:'M\xfclkiyet / Yetki',ilke:'Devletin \u201cyetki\u201d (jurisdiction) alan\u0131, kendi s\u0131n\u0131rlar\u0131yla s\u0131n\u0131rl\u0131 de\u011fildir; bir b\xf6lgede fiil\xee ve etkin genel kontrol (effective overall control) uygulayan devlet, orada S\xf6zle\u015fme\u2019den sorumlu olur.',olay:'K\u0131br\u0131sl\u0131 Rum ba\u015fvurucu, K\u0131br\u0131s\u2019\u0131n kuzeyindeki ta\u015f\u0131nmazlar\u0131na eri\u015fiminin s\xfcrekli olarak engellendi\u011fini; bunun m\xfclkiyet hakk\u0131n\u0131 ihlal etti\u011fini ileri s\xfcrm\xfc\u015ft\xfcr.',degerlendirme:'Mahkeme, b\xf6lgedeki asker mevcudiyeti nedeniyle T\xfcrkiye\u2019nin etkin genel kontrol uygulad\u0131\u011f\u0131n\u0131; ba\u015fvurucunun ta\u015f\u0131nmaz\u0131na eri\u015fiminin s\xfcrekli engellenmesinin m\xfclkiyetin kullan\u0131m\u0131ndan yoksun b\u0131rakma niteli\u011finde, s\xfcregelen (continuing) bir ihlal olu\u015fturdu\u011funu belirtmi\u015ftir.',sonuc:'1 No\u2019lu Protokol m. 1 ihlali.',onem:'\u201cEtkin kontrol\u201d ve devletin s\u0131n\u0131r \xf6tesi sorumlulu\u011fu (extraterritorial jurisdiction) doktrininin \xf6nc\xfc karar\u0131d\u0131r. Uluslararas\u0131 sorumluluk ve m\xfclkiyet uyu\u015fmazl\u0131klar\u0131nda d\xf6n\xfcm noktas\u0131d\u0131r.'},{id:'ocalan-2005',slug:'ocalan-turkiye',basvuru:'\xd6calan / T\xfcrkiye',basvuruNo:'46221/99',tarih:'12.05.2005',buyukDaire:!0,madde:'A\u0130HS m. 3, m. 5, m. 6',kategori:'Adil Yarg\u0131lanma',ilke:'B\xfcnyesinde asker\xee h\xe2kim bulunan Devlet G\xfcvenlik Mahkemesi, ba\u011f\u0131ms\u0131z ve tarafs\u0131z mahkeme g\xfcvencesini kar\u015f\u0131lamaz. Adil olmayan bir yarg\u0131lama sonucu verilen \xf6l\xfcm cezas\u0131, m. 3 bak\u0131m\u0131ndan da a\u011f\u0131r sonu\xe7 do\u011furur.',olay:'Ba\u015fvurucu, yakalan\u0131p T\xfcrkiye\u2019ye getirilmi\u015f ve o d\xf6nem yap\u0131s\u0131nda asker\xee h\xe2kim bulunan Devlet G\xfcvenlik Mahkemesi\u2019nde yarg\u0131lanarak \xf6l\xfcm cezas\u0131na mahk\xfbm edilmi\u015ftir (ceza sonradan m\xfcebbede \xe7evrilmi\u015ftir).',degerlendirme:'Mahkeme, DGM\u2019nin ba\u011f\u0131ms\u0131zl\u0131k/tarafs\u0131zl\u0131k ku\u015fkusu do\u011furdu\u011funu ve savunma haklar\u0131n\u0131n k\u0131s\u0131tland\u0131\u011f\u0131n\u0131 (dosyaya/m\xfcdafiye eri\u015fim) tespit etmi\u015f; g\xf6zalt\u0131n\u0131n h\xe2kim \xf6n\xfcne \xe7\u0131kar\u0131lmas\u0131ndaki gecikmeyi m. 5\u2019e ayk\u0131r\u0131 bulmu\u015ftur. Adil olmayan yarg\u0131lama sonucu \xf6l\xfcm cezas\u0131 verilmesinin m. 3 y\xf6n\xfcnden a\u011f\u0131rl\u0131\u011f\u0131na i\u015faret edilmi\u015ftir.',sonuc:'m. 5 ve m. 6 ihlalleri; yeniden yarg\u0131lanma en uygun giderim olarak g\xf6sterildi.',onem:'T\xfcrkiye\u2019de Devlet G\xfcvenlik Mahkemeleri\u2019nin kald\u0131r\u0131lmas\u0131nda ve A\u0130HM ihlaline dayal\u0131 yeniden yarg\u0131lanma yolunun i\u015fletilmesinde belirleyici olmu\u015ftur.'},{id:'dink-2010',slug:'dink-turkiye',basvuru:'Dink / T\xfcrkiye',basvuruNo:'2668/07 vd.',tarih:'14.09.2010',madde:'A\u0130HS m. 2, m. 10, m. 13',kategori:'\u0130fade \xd6zg\xfcrl\xfc\u011f\xfc',ilke:'Devletin ya\u015fam\u0131 koruma pozitif y\xfck\xfcml\xfcl\xfc\u011f\xfc, bilinen ger\xe7ek ve yak\u0131n tehdide kar\u015f\u0131 \xf6nlem almay\u0131 gerektirir. Bir gazetecinin \xf6ld\xfcr\xfclmesi ve ifadeleri nedeniyle mahk\xfbmiyeti, ifade \xf6zg\xfcrl\xfc\u011f\xfc \xfczerinde cayd\u0131r\u0131c\u0131 (chilling) etki yarat\u0131r.',olay:'Gazeteci-yazar Hrant Dink, yaz\u0131lar\u0131 nedeniyle \u201cT\xfcrkl\xfc\u011f\xfc a\u015fa\u011f\u0131lama\u201ddan mahk\xfbm edilmi\u015f; ard\u0131ndan g\xfcvenlik birimlerinin somut suikast tehdidini bilmesine ra\u011fmen koruma sa\u011flanmamas\u0131 sonucu \xf6ld\xfcr\xfclm\xfc\u015ft\xfcr.',degerlendirme:'Mahkeme, yetkililerin ger\xe7ek ve yak\u0131n ya\u015fam tehdidini bildi\u011fini/bilmesi gerekti\u011fini ve makul \xf6nlemleri almad\u0131\u011f\u0131n\u0131 tespit ederek m. 2\u2019nin hem esas hem usul (etkili soru\u015fturma) y\xf6n\xfcnden ihlal edildi\u011fini; mahk\xfbmiyet ve korumas\u0131zl\u0131\u011f\u0131n ifade \xf6zg\xfcrl\xfc\u011f\xfcn\xfc zedeledi\u011fini belirtmi\u015ftir.',sonuc:'m. 2 (esas ve usul), m. 13 ve m. 10 ihlali.',onem:'Ya\u015fam hakk\u0131n\u0131n korunmas\u0131 ile ifade \xf6zg\xfcrl\xfc\u011f\xfcn\xfcn kesi\u015fti\u011fi, T\xfcrkiye a\xe7\u0131s\u0131ndan simgesel ve emsal bir karard\u0131r. Gazetecilerin/muhaliflerin korunmas\u0131 ve ifade \xf6zg\xfcrl\xfc\u011f\xfc davalar\u0131nda g\xfc\xe7l\xfc dayanakt\u0131r.'},{id:'broniowski-2004',slug:'broniowski-polonya',basvuru:'Broniowski / Polonya',basvuruNo:'31443/96',tarih:'22.06.2004',buyukDaire:!0,madde:'1 No\u2019lu Protokol m. 1 (M\xfclkiyet)',kategori:'M\xfclkiyet / Yetki',ilke:'Ayn\u0131 yap\u0131sal (sistemik) sorundan kaynaklanan \xe7ok say\u0131da ba\u015fvuru bulundu\u011funda A\u0130HM \u201cpilot karar\u201d verir; devlete, benzer ma\u011fduriyetleri i\xe7 hukukta topluca giderecek genel tedbirleri alma y\xfck\xfcml\xfcl\xfc\u011f\xfc do\u011far.',olay:'\u0130kinci D\xfcnya Sava\u015f\u0131 sonras\u0131 s\u0131n\u0131r de\u011fi\u015fiklikleriyle terk edilen m\xfclkler i\xe7in \xf6ng\xf6r\xfclen tazmin hakk\u0131, devlet\xe7e fiilen i\u015fletilmemi\u015f; ayn\u0131 durumdaki on binlerce ki\u015fi ma\u011fdur olmu\u015ftur.',degerlendirme:'Mahkeme, sorunun bireysel de\u011fil sistemik oldu\u011funu tespit ederek pilot karar usul\xfcn\xfc uygulam\u0131\u015f; ihlalin kayna\u011f\u0131ndaki mevzuat/uygulama bo\u015flu\u011funun giderilmesini ve benzer ba\u015fvuruculara etkili giderim sa\u011flanmas\u0131n\u0131 istemi\u015ftir.',sonuc:'1 No\u2019lu Protokol m. 1 ihlali; pilot karar usul\xfc uyguland\u0131.',onem:'Sistemik ihlallerde \u201cpilot karar\u201d usul\xfcn\xfcn do\u011fdu\u011fu karard\u0131r. T\xfcrkiye\u2019ye kar\u015f\u0131 yap\u0131sal sorunlarda (\xf6rn. uzun yarg\u0131lama, m\xfclkiyet) bu usul\xfcn uygulanma zeminini anlamak i\xe7in temeldir.'}]},2073,[]);
